package com.ecole.gestion_scolaire.student.controller;
import com.ecole.gestion_scolaire.student.dto.*; import com.ecole.gestion_scolaire.student.service.StudentFamilyInfoService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/students/{studentId}/family-info") public class StudentFamilyInfoController{private final StudentFamilyInfoService service;public StudentFamilyInfoController(StudentFamilyInfoService s){service=s;} @GetMapping @PreAuthorize("hasAuthority('INFO_FAMILIALE_CONSULTER')") public StudentFamilyInfoResponse get(@PathVariable Long studentId){return service.findByStudent(studentId);} @PutMapping @PreAuthorize("hasAuthority('INFO_FAMILIALE_GERER')") public StudentFamilyInfoResponse save(@PathVariable Long studentId,@Valid @RequestBody StudentFamilyInfoRequest r){return service.save(studentId,r);}}
